'use strict';
// Official brand assets, served locally. Provenance: docs/brand-logos.md.
(()=>{
 const brands=[{"key":"capitalone","label":"Capital One","src":"data:image/png;base64,"},{"key":"creditone","label":"Credit One Bank","src":"data:image/png;base64,"},{"key":"elga","label":"ELGA Credit Union","src":"data:image/png;base64,"},{"key":"consumers","label":"Consumers Energy","src":"data:image/png;base64,"},{"key":"indigo","label":"Indigo","src":"data:image/svg+xml;base64,"},{"key":"milestone","label":"Milestone","src":"data:image/svg+xml;base64,"},{"key":"spectrum","label":"Spectrum","src":"data:image/svg+xml;base64,"},{"key":"sun","label":"Sun Communities","src":"data:image/png;base64,"},{"key":"affirm","label":"Affirm","src":"data:image/png;base64,"}];
 const patterns=[/\b(?:capital\s*one|cap\s*one)\b/i,/\bcredit\s*one\b/i,/\belga\b/i,/\bconsumers?\s+energy\b/i,/\bindigo\b/i,/\bmilestone\b/i,/\b(?:spectrum|charter)\b/i,/\bsun\s+(?:communities|homes)\b/i,/\baffirm\b/i];
 window.BearDenBrands={find(name){const index=patterns.findIndex(pattern=>pattern.test(name));return index<0?null:brands[index];}};
})();
